USE sakila;
SHOW TABLES;

##1. List the number of films per category.
SELECT c.name, COUNT(*)  FROM film f
LEFT JOIN film_category ct
ON f.film_id=ct.film_id
LEFT JOIN category c 
ON ct.category_id=c.category_id
GROUP BY ct.category_id;

##2. Retrieve the store ID, city, and country for each store.
SELECT store_id, city, country  FROM store s
JOIN address a
ON s.address_id= a.address_id
JOIN city as c
ON a.city_id = c.city_id
JOIN country ctr
ON c.country_id=ctr.country_id;

##3. Calculate the total revenue generated by each store in dollars.
SELECT store_id, SUM(amount) AS total_revenue FROM store s
JOIN payment p 
ON s.manager_staff_id=p.staff_id
GROUP BY s.store_id;

##4. Determine the average running time of films for each category.
SELECT  c.name, AVG(length) AS avg_running_time FROM film f
LEFT JOIN film_category ct
ON f.film_id=ct.film_id
LEFT JOIN category c 
ON ct.category_id=c.category_id
GROUP BY ct.category_id; 

## BONUS

#5. Identify the film categories with the longest average running time.
SELECT  c.name, AVG(length) AS avg_running_time FROM film f
LEFT JOIN film_category ct
ON f.film_id=ct.film_id
LEFT JOIN category c 
ON ct.category_id=c.category_id
GROUP BY ct.category_id
ORDER BY avg_running_time DESC
LIMIT 1; 

##6. Display the top 10 most frequently rented movies in descending order.
SELECT f.title, COUNT(*) AS rental_freq FROM rental r 
LEFT JOIN inventory iv 
ON r.inventory_id=iv.inventory_id
LEFT JOIN film f 
ON iv.film_id=f.film_id
GROUP BY f.film_id
ORDER BY rental_freq DESC
LIMIT 10;

##7. Determine if "Academy Dinosaur" can be rented from Store 1. 
SELECT f.film_id, t.store_id, f.title FROM film f 
LEFT JOIN 
(SELECT s.store_id, iv.film_id FROM inventory iv
LEFT JOIN store s 
ON iv.store_id=s.store_id) t
ON f.film_id=t.film_id
WHERE title="ACADEMY DINOSAUR";

##8 Provide a list of all distinct film titles, along with their availability status in the inventory.
SELECT DISTINCT f.title,
CASE
	WHEN IFNULL(f.title,"MISSING")="MISSING" THEN "NOT AVAILABLE"
    ELSE "AVAILABLE"
END AS Availabilty
FROM inventory iv
LEFT JOIN film f 
ON iv.film_id=f.film_id;


